wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(34667013394921822205)
,p_plug_name=>'OSvC last refresh'
,p_static_id=>'osvc-last-refresh'
,p_parent_plug_id=>wwv_flow_imp.id(33723148865112114835)
,p_escape_on_http_output=>'N'
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_refresh_date VARCHAR2(100);',
'BEGIN',
'  SELECT TO_CHAR(MAX(CREATED), ''DD-Mon-YYYY HH:MI AM'')',
'    INTO v_refresh_date',
'    FROM AUD_OSVC_MAIL;',
'',
'  HTP.P(''<p style="color: #0077cc; font-family: Arial, sans-serif;">'');',
'  IF v_refresh_date IS NOT NULL THEN',
'    HTP.P(''<strong>Note: Loading data for a new quarter will fetch data from the OSvC report last updated on :</strong> '' || v_refresh_date);',
'  ELSE',
'    HTP.P(''<strong>Note: No data found. Please load OSvC report data first.</strong>'');',
'  END IF;',
'  HTP.P(''</p>'');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_required_role=>wwv_flow_imp.id(33442335837402780889)
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_system VARCHAR2(64);',
'BEGIN',
'    SELECT TYPE_NAME',
'      INTO v_system',
'      FROM AUD_TYPE',
'     WHERE TYPE_ID = :P2_TYPE;',
'',
'    RETURN (UPPER(v_system) = ''OSVC'');',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN FALSE;',
'END;'))
,p_plug_display_when_cond2=>'PLSQL'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(33441426688708337611)
,p_plug_name=>'Report'
,p_static_id=>'report'
,p_region_name=>'my_grid'
,p_parent_plug_id=>wwv_flow_imp.id(33723148865112114835)
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent2:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_query VARCHAR2(4000);',
'   ',
'     ',
'BEGIN',
'     v_query := q''[ SELECT MAIN_ID,',
'                           TYPE_ID,',
'                           FINANCIAL_YEAR,',
'                           QUARTER,',
'                        CASE',
'                        WHEN EXISTS (',
'                            SELECT 1 ',
'                            FROM AUD_MAIN am2 ',
'                            WHERE am2.USER_NAME = am.USER_NAME',
'                            AND am2.TYPE_ID = am.TYPE_ID',
'                            AND am2.FINANCIAL_YEAR || am2.QUARTER != am.FINANCIAL_YEAR || am.QUARTER )',
'                        THEN ''User exist already''',
'                        ELSE ''New user found''',
'                        END AS is_user,',
'                           USER_NAME,',
'                           APPLICATION_NAME,',
'                           ROLE,',
'                           DIRECTOR_ID,',
'                           USER_VALIDATION,',
'                        ',
'                           CREATED_BY,',
'                           UPDATED_BY,',
'                           ADMIN_JUSTIFICATION,',
'                           STATUS ,',
'                        ',
'                           REGION,',
'                           GENERIC_EMAIL,',
'                           COUNTRY,',
'                           SCOPENAME,',
'                           DETAILDATA,',
'                            JSON_VALUE(BANK, ''$."BNP PAYROLL / FRORACLE02"'') AS BNP_FRORACLE02,',
'               JSON_VALUE(BANK, ''$."B1_Status"'') AS B1_Status,',
'               JSON_VALUE(BANK, ''$."BofA / Payroll"'') AS BOFA_Payroll,',
'               JSON_VALUE(BANK, ''$."B2_Status"'') AS B2_Status,',
'               JSON_VALUE(BANK, ''$."JPM / ORACLEPAY"'') AS JPM_ORACLEPAY,',
'               JSON_VALUE(BANK, ''$."B3_Status"'') AS B3_Status,',
'               JSON_VALUE(BANK, ''$."Citi / Payroll"'') AS Citi_Payroll,',
'               JSON_VALUE(BANK, ''$."B4_Status"'') AS B4_Status,',
'               ',
'               JSON_VALUE(BANK, ''$."Assignment Status"'') AS Assignment_Status',
'                    FROM AUD_MAIN am WHERE 1=1  ]'';',
'    IF AUD_PKG.is_admin_access(:APP_USER) = ''Y'' and  :P2_YEAR is not null and  :P2_QUARTER is not null and  :P2_TYPE is not null  THEN',
'',
'         v_query := v_query || '' AND FINANCIAL_YEAR = '' || :P2_YEAR || '' AND QUARTER = '''''' ||:P2_QUARTER ||'''''' AND TYPE_ID = '' || :P2_TYPE;',
'    ELSIF AUD_PKG.is_director_access(:APP_USER) = ''Y'' and  :P2_YEAR is not null and  :P2_QUARTER is not null and  :P2_TYPE is not null  THEN',
'        v_query := v_query || '' AND FINANCIAL_YEAR = '' || :P2_YEAR || '' AND QUARTER = '''''' ||:P2_QUARTER ||'''''' AND TYPE_ID = '' || :P2_TYPE||  '' AND DIRECTOR_ID IN (SELECT id FROM AUD_DIRECTOR WHERE UPPER(DIRECTOR) = UPPER( '''''' ||:APP_USER|| ''''''))'';',
'',
'    ELSE',
'        v_query := v_query || '' AND 1 = 2'';  -- Returns no data',
'    END if;',
'        v_query := v_query || '' ORDER BY CASE is_user WHEN ''''New user found'''' THEN 1 '' ||',
'                                           ''WHEN ''''User exist already'''' THEN 2 ELSE 3 END'';',
'    RETURN v_query ;',
'',
'',
'END  ;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P2_YEAR,P2_QUARTER,P2_TYPE'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
