wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(112311228542217516)
,p_name=>'P2_ACCESS_REQUEST_TEMPLATES'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(33441426688708337611)
,p_item_display_point=>'EDIT'
,p_use_cache_before_default=>'NO'
,p_prompt=>'Access Request Templates'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_raw varchar2(4000);',
'  l_url varchar2(4000);',
'begin',
'  select web_template_html',
'    into l_raw',
'    from aud_template',
'   where template_name = ''Access Request Templates Link'';',
'',
'  l_url := regexp_replace(l_raw, ''<[^>]+>'', '''');',
'  l_url := trim(l_url);',
'',
'  if not regexp_like(l_url, ''^https?://'', ''i'') then',
'    return null;',
'  end if;',
'',
'  return ''<a href="'' || apex_escape.html_attribute(l_url) ||',
'''" target="_blank" rel="noopener" '' ||',
'''style="background:#2f2f2f; color:#ffffff; font-weight:700; ''||',
'''padding:10px 18px; display:inline-flex; align-items:center; gap:8px; ''||',
'''border-radius:6px; text-decoration:none; line-height:1; ''||',
'''box-shadow:0 1px 0 rgba(0,0,0,.25);">'' ||',
'''View Request Templates</a>'' ; ',
'',
'exception',
'  when no_data_found then',
'    return null;',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_field_template=>2040785906935475274
,p_item_template_options=>'#DEFAULT#'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
