wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(33142683607194074425)
,p_name=>'P2_TYPE'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(33723148865112114835)
,p_prompt=>'System'
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_query VARCHAR2(4000);',
'BEGIN',
'    v_query := q''[SELECT TYPE_NAME D, TYPE_ID R FROM AUD_TYPE WHERE 1=1]'';',
'',
'    IF AUD_PKG.is_admin_access(:APP_USER) = ''Y''',
'       AND :P2_YEAR IS NOT NULL',
'       AND :P2_QUARTER IS NOT NULL',
'    THEN',
'        -- Admin: no additional filters',
'        NULL;',
'',
'    ELSIF AUD_PKG.is_director_access(:APP_USER) = ''Y''',
'          AND :P2_YEAR IS NOT NULL',
'          AND :P2_QUARTER IS NOT NULL',
'    THEN',
'        -- Director: add director-specific filter',
'        v_query := v_query ||',
'          '' AND TYPE_ID IN ('' ||',
'          ''SELECT DISTINCT TYPE_ID FROM AUD_MAIN WHERE FINANCIAL_YEAR = '' || :P2_YEAR ||',
'          '' AND QUARTER = '''''' || :P2_QUARTER || '''''''' ||',
'          '' AND DIRECTOR_ID = (SELECT ID FROM AUD_DIRECTOR WHERE UPPER(DIRECTOR) = UPPER('''''' || :APP_USER || ''''''))'' ||',
'          '')'';',
'',
'    ELSE',
'        -- No authorized access or incomplete selection: Return empty',
'        v_query := v_query || '' AND 1=2'';',
'    END IF;',
'',
'    RETURN v_query ;',
'END;'))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P2_YEAR,P2_QUARTER'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_begin_on_new_line=>'N'
,p_field_template=>1609121967514267634
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_updated_on=>wwv_flow_imp.dz('20260123052250Z')
,p_updated_by=>'ROHIT.BQ.KUMAR@ORACLE.COM'
);
