wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10921004301909469737)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Filtered Data keep'
,p_static_id=>'process-filtered-data-keep'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_report_id          number;',
'    l_region_id          apex_application_page_regions.region_id%type;',
'    l_context            apex_exec.t_context;',
'    l_empno              AUD_MAIN.main_id%type;',
'    l_idx_empno          pls_integer;',
'    l_filtered_rows_clob clob := empty_clob();',
'    l_first              boolean := TRUE;',
'    p_director_id AUD_DIRECTOR.ID%TYPE;',
'begin',
'    -- Check presence of required parameters',
'    IF :P2_YEAR IS NULL OR :P2_QUARTER IS NULL OR :P2_TYPE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Year, quarter, or type selection is missing.'');',
'    END IF;',
'      -- Attempt to find the director, raise error if not exactly one found',
'    BEGIN',
'        SELECT id',
'        INTO p_director_id',
'        FROM AUD_DIRECTOR',
'        WHERE director = :app_user;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RAISE_APPLICATION_ERROR(-20002, ''No director found for this user.'');',
'        WHEN TOO_MANY_ROWS THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''Multiple directors found for this user.'');',
'    END;',
'',
'    -- Get the internal region id based on the "Static ID" given for IG region',
'    select region_id',
'      into l_region_id',
'      from apex_application_page_regions',
'     where application_id = :APP_ID',
'       and page_id        = :APP_PAGE_ID',
'       and static_id      = ''my_grid'';',
'',
'    -- Get the last viewed report id based on region id',
'    l_report_id := apex_ig.get_last_viewed_report_id (',
'        p_page_id   => :APP_PAGE_ID,',
'        p_region_id => l_region_id',
'    );',
'',
'    -- Open query context for the region and report using region id and report id',
'    l_context := apex_region.open_query_context (',
'        p_page_id      => :APP_PAGE_ID,',
'        p_region_id    => l_region_id,',
'        p_component_id => l_report_id',
'    );',
'',
'    -- get column position based on column name',
'    l_idx_empno := apex_exec.get_column_position( l_context, ''MAIN_ID'' );',
'',
'    -- Fetch and loop through the rows using the query context',
'    while apex_exec.next_row( l_context )',
'    loop',
'        l_empno := apex_exec.get_number (p_context => l_context, p_column_idx => l_idx_empno);',
'        if l_first then',
'            l_filtered_rows_clob := to_clob(l_empno);',
'            l_first := FALSE;',
'        else',
'            dbms_lob.writeappend(l_filtered_rows_clob,2,'', '');',
'            dbms_lob.writeappend(l_filtered_rows_clob,length(to_char(l_empno)),to_char(l_empno));',
'        end if;',
'    end loop;',
'',
'    apex_exec.close( l_context );',
'',
'    -- Assign the result to a CLOB page item (make sure :P1_SELECTED_IDS is of type CLOB)',
'    -- :P1_SELECTED_IDS := l_filtered_rows_clob;',
'     -- Perform the update',
'    UPDATE AUD_MAIN',
'       SET USER_VALIDATION = ''Keep user''',
'     WHERE FINANCIAL_YEAR = :P2_YEAR',
'       AND QUARTER = :P2_QUARTER',
'       AND TYPE_ID = :P2_TYPE',
'       AND DIRECTOR_ID = p_director_id',
'       AND MAIN_ID IN (',
'    SELECT TO_NUMBER(COLUMN_VALUE)',
'      FROM TABLE(apex_string.split(l_filtered_rows_clob, '',''))',
');',
'',
'exception',
'    when others then',
'        apex_exec.close( l_context );',
'        raise;',
'end;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(33723149402349114840)
,p_internal_uid=>25963006315058453849
,p_created_on=>wwv_flow_imp.dz('20260212063735Z')
,p_updated_on=>wwv_flow_imp.dz('20260618082226Z')
,p_created_by=>'ROHIT.BQ.KUMAR@ORACLE.COM'
,p_updated_by=>'MAREK.SZWARCZEWSKI@ORACLE.COM'
);
