wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112313050097217534)
,p_process_sequence=>100
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'restore_selectedSystem'
,p_static_id=>'restore-selectedsystem'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_status aud_year_quarter_tracker.status%type;',
'begin',
'  -- validate inputs',
'  if :P2_YEAR is null or :P2_QUARTER is null or :P2_TYPE is null then',
'    raise_application_error(-20001, ''Reset allowed only when Year, Quarter, and System are selected.'');',
'  end if;',
'',
'  -- get status for the selected year/quarter',
'  begin',
'    select status',
'      into l_status',
'      from aud_year_quarter_tracker',
'     where year    = :P2_YEAR',
'       and quarter = :P2_QUARTER;',
'  exception',
'    when no_data_found then',
'      raise_application_error(-20002, ''No tracker record found for the selected Year/Quarter.'');',
'    when too_many_rows then',
'      raise_application_error(-20003, ''Multiple tracker records found for the selected Year/Quarter.'');',
'  end;',
'',
'  -- allow reset only if WIP',
'  if l_status <> ''WIP'' then',
'    raise_application_error(-20004, ''Reset allowed only when the Quarter status is WIP.'');',
'  end if;',
'',
'  -- perform reset (delete)',
'  delete from aud_main',
'   where quarter        = :P2_QUARTER',
'     and financial_year = :P2_YEAR',
'     and type_id        = :P2_TYPE;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112312694922217531)
,p_internal_uid=>36996323667065141120
,p_created_on=>wwv_flow_imp.dz('20260227042301Z')
,p_updated_on=>wwv_flow_imp.dz('20260618082226Z')
,p_created_by=>'ROHIT.BQ.KUMAR@ORACLE.COM'
,p_updated_by=>'MAREK.SZWARCZEWSKI@ORACLE.COM'
);
