,p_region_id=>wwv_flow_imp.id(33441426688708337611)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'save report (new edit report)'
,p_static_id=>'save-report-new-edit-report'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    p_director_id AUD_DIRECTOR.ID%TYPE;',
'begin',
'    -- Check presence of required parameters',
'    IF :P2_YEAR IS NULL OR :P2_QUARTER IS NULL OR :P2_TYPE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Year, quarter, or type selection is missing.'');',
'    END IF;',
'      -- Attempt to find the director, raise error if not exactly one found',
'    BEGIN',
'        SELECT id',
'        INTO p_director_id',
'        FROM AUD_DIRECTOR',
'        WHERE director = :app_user;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RAISE_APPLICATION_ERROR(-20002, ''No director found for this user.'');',
'        WHEN TOO_MANY_ROWS THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''Multiple directors found for this user.'');',
'    END;',
'',
'    pcg.log(''Audit.18101'',''page2.save_report'',''2026-06-18 17:00'',''[USER_VALIDATION: ''||:USER_VALIDATION||''; P2_YEAR: ''||:P2_YEAR||',
'            ''; P2_QUARTER: ''||:P2_QUARTER||'';  P2_TYPE: ''||:P2_TYPE||'';  DIRECTOR_ID: ''||p_director_id||'';  MAIN_ID: ''||:MAIN_ID||',
'            '']'',null,''DEBUG'');',
'',
'     -- Perform the update',
'    UPDATE AUD_MAIN',
'       SET USER_VALIDATION = :USER_VALIDATION',
'     WHERE FINANCIAL_YEAR = :P2_YEAR',
'       AND QUARTER = :P2_QUARTER',
'       AND TYPE_ID = :P2_TYPE',
'       AND DIRECTOR_ID = p_director_id',
'       AND MAIN_ID = :MAIN_ID;',
'',
'exception',
'    when others then raise;',
'end;',
''))
