,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'send to director'
,p_static_id=>'send-to-director'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'p_status varchar2(32);',
'',
'begin ',
'-- select STATUS into p_status from AUD_YEAR_QUARTER_TRACKER where YEAR = :P2_YEAR and QUARTER = :P2_QUARTER ; ',
'-- if p_status != ''WIP'' then ',
'--      RAISE_APPLICATION_ERROR(-20001, ''Status for selected Quarter is not WIP'') ; ',
'-- else ',
'    AUD_PKG.send_mail_to_director (:P2_YEAR , :P2_QUARTER);',
'-- end if ; ',
'',
'end ; '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(33370777468793962840)
,p_security_scheme=>wwv_flow_imp.id(33442335837402780889)
,p_internal_uid=>784471917329173939
,p_updated_on=>wwv_flow_imp.dz('20260211073659Z')
,p_updated_by=>'ROHIT.BQ.KUMAR@ORACLE.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34064555037831137003)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SUBMIT BY DIRECTOR'
,p_static_id=>'submit-by-director'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'l_director_id aud_director.id%type;',
'l_missing_type aud_type.type_name%type;',
'l_cnt number;',
'',
'begin',
'-- Find director for the current APEX user (case-insensitive)',
'select id',
'into l_director_id',
'from aud_director',
'where upper(director) = upper(:app_user);',
'',
'-- Basic parameter checks',
'if :P2_YEAR is null or :P2_QUARTER is null then',
'raise_application_error(-20020, ''Year and Quarter are required.'');',
'end if;',
'',
'-- Check if any user validations are missing for this director/year/quarter',
'begin',
'select t.type_name',
'into l_missing_type',
'from aud_main a',
'join aud_type t',
'on t.type_id = a.type_id',
'where a.financial_year = :P2_YEAR',
'and a.quarter = :P2_QUARTER',
'and a.director_id = l_director_id',
'and a.user_validation is null',
'and rownum = 1; -- get any one offending system',
'',
'-- If we got here, at least one system is missing validation',
'raise_application_error(',
'-20010,',
'''Please ensure that User Validation is completed for all users across all systems before submitting. System '' ||',
'l_missing_type || '' is not completed''',
');',
'exception',
'when no_data_found then',
'null; -- all validations complete',
'end;',
'',
'-- All good: update status and send mail',
'update aud_main',
'set status = ''Reviewed by Director''',
'where financial_year = :P2_YEAR',
'and quarter = :P2_QUARTER',
'and director_id = l_director_id;',
'',
'-- If no remaining rows in this quarter are still ''Sent to Director'', update tracker',
'select count(*)',
'into l_cnt',
'from aud_main',
'where financial_year = :P2_YEAR',
'and quarter = :P2_QUARTER',
'and status = ''Sent to Director'';',
'',
'if l_cnt = 0 then',
'    update aud_year_quarter_tracker',
'    set status = ''Reviewed by Director''',
'    where year = :P2_YEAR',
'    and quarter = :P2_QUARTER;',
'    ',
'    aud_pkg.send_mail_to_admin(:P2_YEAR, :P2_QUARTER, l_director_id);',
'',
'end if;',
'',
'exception',
'when no_data_found then',
'-- from the director lookup',
'raise_application_error(-20001, ''No Director found for APEX user: '' || :APP_USER);',
'when too_many_rows then',
'raise_application_error(-20002, ''Multiple director rows match user '' || :APP_USER || ''. Please fix the mapping.'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(34064554830020137001)
,p_process_success_message=>'Submitted !'
,p_internal_uid=>1207414320436319811
,p_updated_on=>wwv_flow_imp.dz('20260820054330Z')
,p_updated_by=>'PRAGYA.KAPOOR@ORACLE.COM'
);
end;
