wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33502605278251083533)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(33502604368888083524)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Director_map - Save Interactive Grid Data'
,p_static_id=>'director-map-save-interactive-grid-data'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'dml_plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    'p_quarter varchar2(32) ; ',
    'p_year number ;',
    '',
    'BEGIN -- It runs row by row for interactive grid',
    '    IF :APEX$ROW_STATUS = ''D'' THEN -- DELETE',
    '        DELETE FROM AUD_DIRECTOR_MAP',
    '        WHERE ID= :ID; -- Column name',
    '        --RETURN;',
    '    ELSIF :APEX$ROW_STATUS = ''C'' THEN -- CREATE',
    '        INSERT INTO AUD_DIRECTOR_MAP',
    '            (USER_NAME, DIRECTOR_AUTOMATION_ID, DIRECTOR_ID, TYPE_ID, LOC)',
    '        VALUES',
    '            (upper(:USER_NAME),  AUD_PKG.get_director_id(upper(:USER_NAME)) , :DIRECTOR_ID, :TYPE_ID, :LOC); ',
    '        --RETURN;',
    '    ELSIF :APEX$ROW_STATUS = ''U'' THEN -- UPDATE',
    '        UPDATE AUD_DIRECTOR_MAP',
    '        SET USER_NAME = upper(:USER_NAME), ',
    '        -- DIRECTOR_AUTOMATION_ID =  AUD_PKG.get_director_id(upper(:USER_NAME)) , ',
    '        DIRECTOR_ID = :DIRECTOR_ID, ',
    '        TYPE_ID = :TYPE_ID,',
    '        LOC = :LOC',
    '        WHERE ID = :ID; ',
    '        --RETURN;',
    '    END IF;',
    '',
    '',
    'select YEAR , QUARTER into p_year, p_quarter from AUD_YEAR_QUARTER_TRACKER where STATUS = ''WIP'' ; ',
    '',
    'if p_year is not null and p_quarter is not null then ',
    'FOR i in (select TYPE_ID from AUD_TYPE where TYPE_ID != 0 ) loop',
    'AUD_PKG.update_director_all(',
