,p_process_name=>'YEAR_QUARTER_TRACKER - Save Interactive Grid Data'
,p_static_id=>'year-quarter-tracker-save-interactive-grid-data'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'dml_plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare ',
    'flag number := 0 ;',
    '',
    'begin',
    'SELECT COUNT(*) into flag FROM AUD_YEAR_QUARTER_TRACKER WHERE STATUS = ''WIP'' ;',
    '',
    ' case :APEX$ROW_STATUS',
    '    when ''C'' then',
    '        IF flag > 0 and :STATUS = ''WIP'' THEN',
    '                RAISE_APPLICATION_ERROR(-20001, ''Only one record with STATUS = ''''WIP'''' is allowed.'');',
    '        END IF;',
    '        insert into AUD_YEAR_QUARTER_TRACKER ( YEAR, QUARTER, STATUS )',
    '        values ( :YEAR, :QUARTER, :STATUS );',
    '       ',
    '        RETURN;',
    '    when ''U'' then',
    '        update AUD_YEAR_QUARTER_TRACKER',
    '           set YEAR  = :YEAR,',
    '               QUARTER = :QUARTER,',
    '               STATUS = :STATUS',
    '         where ID  = :ID;',
    '          RETURN;',
    '    when ''D'' then',
    '        delete AUD_YEAR_QUARTER_TRACKER',
    '        where ID  = :ID;',
    '         RETURN;',
    '    end case;',
    'end;')),
  'lock_row', 'Y',
  'prevent_lost_updates', 'Y',
  'target_type', 'PLSQL_CODE')).to_clob
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
