wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33502603431658083515)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load File Data_code'
,p_static_id=>'load-file-data-code'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'BEGIN ',
'AUD_PKG.AUD_INSERT(:P10_FILE);',
'END ; '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(33502601280525083493)
,p_process_success_message=>'Uploaded'
,p_internal_uid=>645462714263266323
,p_process_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'p_type_id number := :P10_TYPE;',
'p_year number := :P10_YEAR ;',
'p_quarter varchar2(32) := :P10_QUARTER ;',
'v_exist number ; ',
'',
'',
'cursor c_data is ',
'    select ',
'	   p.col001, p.col002,p.col003',
'from apex_application_temp_files f, ',
'       table( apex_data_parser.parse(',
'                  p_content           => f.blob_content,',
'                  p_file_name         => f.filename,',
'                  p_file_profile      => apex_data_loading.get_file_profile( p_static_id => ''Load_Data''),',
'                  p_max_rows          => 5000 ) ) p',
' where f.name = :P10_FILE AND p.line_number != 1;',
'',
'',
'',
'',
'',
'',
'begin ',
'delete from AUD_MAIN where QUARTER = p_quarter and FINANCIAL_YEAR = p_year and TYPE_ID = p_type_id; ',
'for i in c_data',
'loop',
'',
'',
'Insert into AUD_MAIN(TYPE_ID,FINANCIAL_YEAR,QUARTER,USER_NAME,APPLICATION_NAME,ROLE,DIRECTOR_ID) ',
'values(p_type_id,p_year,p_quarter,upper(i.col001),i.col002,i.col003,-1);',
'',
'-- end if;',
'',
'end loop;',
'',
'if p_year is not null and p_quarter is not null and p_type_id is not null then ',
'',
'AUD_PKG.update_director_all(',
'    p_year , p_quarter ,p_type_id , 0',
') ; ',
'',
'',
'end if ;',
'',
'',
' ',
'',
'end;',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(34060304291735975107)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'page_load'
,p_static_id=>'page-load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'if :P10_FILE is not null then ',
'SELECT ',
'             p.col002,',
'            p.col005,  p.col008 into :P10_YEAR , :P10_QUARTER , :P10_SYSTEM',
'        FROM apex_application_temp_files f,',
'             TABLE(apex_data_parser.parse(',
'                 p_content      => f.blob_content,',
'                 p_file_name    => f.filename,',
'                 p_file_profile => apex_data_loading.get_file_profile(p_static_id => ''Load_Data''),',
'                 p_max_rows     => 1',
'             )) p',
'        WHERE f.name = :P10_FILE AND p.line_number = 1;',
'',
'',
'end if ; ',
'',
'end ; '))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1203163574341157915
);
end;
